import{_ as t,o as a,c as s,a0 as n}from"./chunks/framework.BxCN1dRw.js";const u=JSON.parse('{"title":"Walkthrough: Saving your first Markdown document","description":"","frontmatter":{"docLocale":"en","counterpart":"/tutorials/personal-documents"},"headers":[],"relativePath":"en/tutorials/personal-documents.md","filePath":"en/tutorials/personal-documents.md"}'),r={name:"en/tutorials/personal-documents.md"};function i(o,e,d,h,c,l){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="walkthrough-saving-your-first-markdown-document" tabindex="-1">Walkthrough: Saving your first Markdown document <a class="header-anchor" href="#walkthrough-saving-your-first-markdown-document" aria-label="Permalink to &quot;Walkthrough: Saving your first Markdown document&quot;">​</a></h1><p>Run <code>just dev</code>, register or sign in, and open &quot;My documents&quot; from the shared shell&#39;s sidebar. A new account first sees the empty state; click &quot;New document&quot;, enter a title and Markdown, then click &quot;Save document&quot;. Refresh the detail page — the content is still read from PostgreSQL.</p><p>An ordinary Member does not wait for an administrator to create a knowledge base. The first successful save prepares the personal Knowledge Base, the Editor Grant, the Document and the corresponding audit in the same transaction. This chapter shows creation, listing and reading the original content; the <a href="./search-preview">next chapter</a> adds safe preview and search, and concurrent editing arrives in a later chapter.</p><p>The chapter&#39;s fixed copy comes from the knowledge example&#39;s bilingual message catalog; the UI language switches on the register page, the sign-in page or under &quot;Appearance &amp; language&quot;. Operation names stay consistent across Chinese and English:</p><table tabindex="0"><thead><tr><th>Page element</th><th>Chinese</th><th>English</th></tr></thead><tbody><tr><td>Business nav</td><td>我的文档</td><td>My documents</td></tr><tr><td>New action</td><td>新建文档</td><td>New document</td></tr><tr><td>Title field</td><td>标题</td><td>Title</td></tr><tr><td>Body field</td><td>Markdown 正文</td><td>Markdown body</td></tr><tr><td>Save action</td><td>保存文档</td><td>Save document</td></tr><tr><td>Edit entry</td><td>编辑文档</td><td>Edit document</td></tr><tr><td>Load more</td><td>加载更多</td><td>Load more</td></tr></tbody></table><h2 id="_1-keeping-the-business-in-its-own-module" tabindex="-1">1. Keeping the business in its own module <a class="header-anchor" href="#_1-keeping-the-business-in-its-own-module" aria-label="Permalink to &quot;1. Keeping the business in its own module&quot;">​</a></h2><p>The knowledge base&#39;s <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/d209def654c8bab1a92fe98f8cd614cc87b674d4/crates/app/src/modules/knowledge/domain.rs" target="_blank" rel="noreferrer">pure content rules</a> limit the title to 1–200 characters and Markdown UTF-8 content to 1 MiB, and reject NUL bytes that PostgreSQL text cannot store. The rules live in the module&#39;s own Domain file and can be adapted to your product without pushing knowledge-base concepts into Core.</p><p>The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/d209def654c8bab1a92fe98f8cd614cc87b674d4/crates/app/src/modules/knowledge/application.rs" target="_blank" rel="noreferrer">Application use case</a> orchestrates the transaction and permissions; the <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/d209def654c8bab1a92fe98f8cd614cc87b674d4/crates/app/src/modules/knowledge/mod.rs" target="_blank" rel="noreferrer">HTTP interface</a> handles the protocol and public errors. The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/d209def654c8bab1a92fe98f8cd614cc87b674d4/migrations/0003_knowledge.sql" target="_blank" rel="noreferrer">business migration</a> owns only the tables of the <code>knowledge</code> schema — Core&#39;s registration neither creates personal knowledge bases nor calls these use cases.</p><p>The first write coordinates concurrency with the <code>personal_owner</code> unique constraint. Only the transaction that actually creates a new knowledge base grants Editor; writes against an existing knowledge base missing the grant are rejected, and retrying initialization never quietly restores a revoked permission. Owner/Admin can access every organization knowledge base under the confirmed rules; other ordinary members need a Grant for that knowledge base.</p><p>Writes lock the current membership through Organization&#39;s public interface and hold the knowledge base&#39;s shared lock while checking the grant. Later role deactivations and grant changes can take the corresponding exclusive lock, forming an explicit commit order.</p><h2 id="_2-one-transaction-protects-one-save" tabindex="-1">2. One transaction protects one save <a class="header-anchor" href="#_2-one-transaction-protects-one-save" aria-label="Permalink to &quot;2. One transaction protects one save&quot;">​</a></h2><p>Creating the knowledge base, granting the default permission, creating the document and the Audit commit together. If the audit fails, every change rolls back — a half-finished &quot;document exists, but the audit or grant is missing&quot; must not happen.</p><p>The document body is stored in PostgreSQL; Markdown is not written to RustFS today — RustFS will serve the later attachments and export binaries.</p><h2 id="_3-making-a-retry-the-same-operation" tabindex="-1">3. Making a retry the same operation <a class="header-anchor" href="#_3-making-a-retry-the-same-operation" aria-label="Permalink to &quot;3. Making a retry the same operation&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/d209def654c8bab1a92fe98f8cd614cc87b674d4/crates/app/src/modules/idempotency/mod.rs" target="_blank" rel="noreferrer">Core Idempotency</a> provides <code>claim</code> / <code>complete</code>; the business holds the transaction and calls them after authorization. The scope covers the account, the operation and the target knowledge base, storing the fingerprint and result of the normalized request. The idempotency record commits in the same transaction as the business/Audit writes; concurrent requests coordinate serially on the same record.</p><p>The same <code>Idempotency-Key</code> with the same content returns the original result; the same key with changed content returns 409. The replay window defaults to 24 hours; expired keys can be reused, and calls reclaim expired records in bounded batches. Replay still checks the session, the current membership and the knowledge base grant — a cache is never treated as authorization.</p><p>The new-document page keeps the key when retrying the same input and generates a new key when the input changes. After a network timeout the user can retry, and the server still produces exactly one document. The SDK never retries POST automatically.</p><h2 id="_4-from-the-contract-to-the-page" tabindex="-1">4. From the contract to the page <a class="header-anchor" href="#_4-from-the-contract-to-the-page" aria-label="Permalink to &quot;4. From the contract to the page&quot;">​</a></h2><p>The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/d209def654c8bab1a92fe98f8cd614cc87b674d4/apps/api/src/lib.rs" target="_blank" rel="noreferrer">API assembly point</a> merges Core&#39;s and Knowledge&#39;s Routers/OpenAPI; the generated SDK exports methods from the combined contract. Core&#39;s Router builder never imports the knowledge module.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> generate</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> contracts:check</span></span></code></pre></div><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/d209def654c8bab1a92fe98f8cd614cc87b674d4/packages/views/src/knowledge/documents-view.tsx" target="_blank" rel="noreferrer">Knowledge Views</a> reuse the Core session, the generated SDK and the common UI. The list returns summaries only, with cursor pagination defaulting to 50 and capped at 100; the cursor binds to the current identity and ordering and cannot be carried across accounts. Every query re-authorizes independently — a cursor is not an access credential.</p><p>The page renders only the workspace content: the sidebar navigation, the page landmark and the role-gated entries come from the shared shell provided by the app adapter, and the business navigation entries plus all copy come from the example&#39;s registered navigation and message catalog. Switching the UI language re-renders the page in place; lists and input survive, and user content stays in its original language.</p><p>This chapter originally wired reading through the raw detail; the current version shows the safe preview as described in the <a href="./search-preview">next chapter</a>. A failed save keeps the input and the request ID; a save response from a previous identity cannot update the new identity&#39;s UI after switching accounts.</p><h2 id="_5-verifying-behaviour-and-removability" tabindex="-1">5. Verifying behaviour and removability <a class="header-anchor" href="#_5-verifying-behaviour-and-removability" aria-label="Permalink to &quot;5. Verifying behaviour and removability&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/test-backend.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> knowledge</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vitest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/web/src/knowledge.test.tsx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/web/src/knowledge-bilingual.test.tsx</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boundaries:check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre></div><p>The backend covers create→read, privacy isolation, initialization/replay rejection after revocation, lock-driven concurrency, idempotent retries and transaction rollback. The View tests check the empty state, new-document navigation, failed saves keeping input and reusing the request key. The bilingual tests verify the representative pages in both languages. Run the key journeys together when they complete:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/e2e.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/e2e/knowledge.spec.ts</span></span></code></pre></div><p>A real browser registers a new Member, saves the first document directly, then refreshes and reopens it from the list.</p><p>The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/d209def654c8bab1a92fe98f8cd614cc87b674d4/examples/knowledge-base/manifest.json" target="_blank" rel="noreferrer">ownership manifest</a> registers the business directories, migrations, tests, tutorials and the few assembly points. Blocks marked <code>example:knowledge</code> are the explicit wiring locations; the later removal tool operates on a fresh copy by the manifest rather than guessing from file names — and never deletes existing production data. Core&#39;s identity, audit, idempotency and common HTTP capabilities remain.</p><hr><p>Source version：<code>d209def654c8</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/d209def654c8bab1a92fe98f8cd614cc87b674d4/docs/tutorials/04-personal-documents.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,31)])])}const g=t(r,[["render",i]]);export{u as __pageData,g as default};
